package com.astra.audit.service;
import com.astra.audit.entity.AuditLog; import com.astra.audit.repository.AuditLogRepository; import org.springframework.data.domain.*; import org.springframework.stereotype.Service;
@Service public class AuditLogService { private final AuditLogRepository repo; public AuditLogService(AuditLogRepository repo){this.repo=repo;} public AuditLog record(AuditLog l){return repo.save(l);} public Page<AuditLog> find(Long userId,String action,Pageable p){if(userId!=null&&action!=null)return repo.findByUserIdAndActionContainingIgnoreCase(userId,action,p); if(userId!=null)return repo.findByUserId(userId,p); if(action!=null)return repo.findByActionContainingIgnoreCase(action,p); return repo.findAll(p);} public AuditLog get(Long id){return repo.findById(id).orElseThrow(()->new IllegalArgumentException("Audit log not found: "+id));} }
